#[test]
fn check_metadata_content_with_multiline_values() {
    // Simulate a doc where depends has continuation lines
    let graph = Graph::import(
        &from_indoc(indoc! {"
            title: Task A
            depends:
              - foo
              - bar
            status: ready

            # Task A
        "}),
        bare_options(),
        None,
    );
    let keys = graph.keys();
    let meta = graph.get_metadata(&keys[0]).unwrap();
    eprintln!("METADATA: {:?}", meta);

    let val: serde_yaml::Value = serde_yaml::from_str(meta).unwrap();
    eprintln!("PARSED: {:?}", val);

    let depends = val.get("depends").unwrap();
    eprintln!("depends: {:?}", depends);

    // This is the key assertion
    assert!(depends.is_sequence(), "depends should be a sequence");
    let seq = depends.as_sequence().unwrap();
    assert!(seq.iter().any(|i| i.as_str() == Some("foo")), "should contain foo");
}
